    "    if at(p, \"switch\"):\n"
    "        return parse_switch(p)\n"
    "    if at(p, \"goto\"):\n"
    "        return parse_goto(p)\n"
    "    if kind(p, \"NAME\") and peekn(p, 1)[\"text\"] = \":\" and not is_kw(peek(p)[\"text\"]):\n"
    "        return parse_label(p)\n"
    "    if at(p, \"if\"):\n"
    "        return parse_if(p)\n"
    "    if at(p, \"while\"):\n"
    "        return parse_while(p)\n"
    "    if at(p, \"for\"):\n"
    "        return parse_for(p)\n"
    "    if at(p, \"return\"):\n"
    "        return parse_return(p)\n"
    "    if at(p, \"break\") or at(p, \"continue\"):\n"
    "        take(p)\n"
    "        z : node(x[\"text\"], x)\n"
    "        need(p, \";\")\n"
    "        return z\n"
    "    if at(p, \"{\"):\n"
    "        fail(p, \"unexpected block\", x)\n"
    "    fn : try_parse_func(p)\n"
    "    if fn != None:\n"
    "        return fn\n"
    "    d : try_parse_decl(p)\n"
    "    if d != None:\n"
    "        return d\n"
    "    return parse_expr_stmt(p)\n"
    "\n"
    "def parse_label(p):\n"
    "    x : take(p)\n"
    "    name : ident(p, x)\n"
    "    need(p, \":\")\n"
    "    z : node(\"Label\", x)\n"
    "    z[\"name\"] : name\n"
    "    return z\n"
    "\n"
    "def parse_goto(p):\n"
    "    x : take(p)\n"
    "    n : need_kind(p, \"NAME\")\n"
    "    need(p, \";\")\n"
    "    z : node(\"Goto\", x)\n"
    "    z[\"name\"] : ident(p, n)\n"
    "    return z\n"
    "\n"
    "def const_zero(x):\n"
    "    z : node(\"Const\", x)\n"
    "    z[\"value\"] : \"0\"\n"
    "    z[\"kind\"] : \"number\"\n"
    "    return z\n"
    "\n"
    "def const_true(x):\n"
    "    z : node(\"Const\", x)\n"
    "    z[\"value\"] : \"True\"\n"
    "    z[\"kind\"] : \"number\"\n"
    "    return z\n"
    "\n"
    "def const_str(x, s):\n"
    "    z : node(\"Const\", x)\n"
    "    z[\"value\"] : s\n"
    "    z[\"kind\"] : \"string\"\n"
    "    return z\n"
    "\n"
    "def name_node(x, s):\n"
    "    z : node(\"Name\", x)\n"
    "    z[\"value\"] : s\n"
    "    return z\n"
    "\n"
    "def assign_name(x, name, value):\n"
    "    z : node(\"Assign\", x)\n"
    "    z[\"target\"] : name_node(x, name)\n"
    "    z[\"value\"] : value\n"
    "    return z\n"
    "\n"
    "def desugar_goto_body(p, body, x):\n"
    "    has : False\n"
    "    for s in body:\n"
    "        if s[\"t\"] = \"Label\" or s[\"t\"] = \"Goto\":\n"
    "            has : True\n"
    "            break\n"
    "    if not has:\n"
    "        return body\n"
    "    # Split top-level body on Label nodes.\n"
    "    segments : []\n"
    "    cur_label : \"\"\n"
    "    cur : []\n"
    "    for s in body:\n"
    "        if s[\"t\"] = \"Label\":\n"
    "            segments.append({\"label\":cur_label, \"body\":cur})\n"
    "            cur_label : s[\"name\"]\n"
    "            cur : []\n"
    "        else:\n"
    "            cur.append(s)\n"
    "    segments.append({\"label\":cur_label, \"body\":cur})\n"
    "    out : []\n"
    "    out.append(assign_name(x, \"__c_goto\", const_str(x, \"\")))\n"
    "    w : node(\"While\", x)\n"
    "    w[\"test\"] : const_true(x)\n"
    "    wbody : []\n"
    "    for seg in segments:\n"
    "        # if __c_goto = \"\" or __c_goto = \"lab\":\n"
    "        test : None\n"
    "        left : name_node(x, \"__c_goto\")\n"
    "        eq1 : node(\"Compare\", x)\n"
    "        eq1[\"left\"] : left\n"
    "        eq1[\"op\"] : \"==\"\n"
    "        eq1[\"right\"] : const_str(x, \"\")\n"
    "        if seg[\"label\"] = \"\":\n"
    "            test : eq1\n"
    "        else:\n"
    "            left2 : name_node(x, \"__c_goto\")\n"
    "            eq2 : node(\"Compare\", x)\n"
    "            eq2[\"left\"] : left2\n"
    "            eq2[\"op\"] : \"==\"\n"
    "            eq2[\"right\"] : const_str(x, seg[\"label\"])\n"
    "            bo : node(\"BoolOp\", x)\n"
    "            bo[\"op\"] : \"or\"\n"
    "            bo[\"values\"] : [eq1, eq2]\n"
    "            test : bo\n"
    "        iff : node(\"If\", x)\n"
    "        iff[\"test\"] : test\n"
    "        iff[\"elifs\"] : []\n"
    "        iff[\"orelse\"] : []\n"
    "        sb : [assign_name(x, \"__c_goto\", const_str(x, \"\"))]\n"
    "        for st in seg[\"body\"]:\n"
    "            if st[\"t\"] = \"Goto\":\n"
    "                sb.append(assign_name(st, \"__c_goto\", const_str(st, st[\"name\"])))\n"
    "                sb.append(node(\"continue\", st))\n"
    "            elif st[\"t\"] = \"Label\":\n"
    "                fail(p, \"nested labels in goto desugar are unsupported\", st)\n"
    "            else:\n"
    "                sb.append(st)\n"
    "        if len(sb) = 0:\n"
    "            sb.append(node(\"pass\", x))\n"
    "        iff[\"body\"] : sb\n"
    "        wbody.append(iff)\n"
    "    wbody.append(node(\"break\", x))\n"
    "    w[\"body\"] : wbody\n"
    "    out.append(w)\n"
    "    return out\n"
    "\n"
    "def parse_struct_fields(p):\n"
    "    need(p, \"{\")\n"
    "    fields : []\n"
    "    while not at(p, \"}\") and not kind(p, \"END\"):\n"
    "        if not skip_type(p):\n"
    "            fail(p, \"expected field type\", peek(p))\n"
    "        reject_pointer_type(p)\n"
    "        while True:\n"
    "            if not kind(p, \"NAME\"):\n"
    "                fail(p, \"expected field name\", peek(p))\n"
    "            ft : take(p)\n"
    "            while at(p, \"[\"):\n"
    "                fail(p, \"array fields are unsupported\", peek(p))\n"
    "            fields.append(ft[\"text\"])\n"
    "            if at(p, \",\"):\n"
    "                take(p)\n"
    "                reject_pointer_type(p)\n"
    "                continue\n"
    "            break\n"
    "        need(p, \";\")\n"
    "    need(p, \"}\")\n"
    "    return fields\n"
    "\n"
    "def parse_struct_or_decl(p):\n"
    "    x : peek(p)\n"
    "    save : p[\"pos\"]\n"
    "    take(p)  # struct\n"
    "    if not kind(p, \"NAME\"):\n"
    "        fail(p, \"expected struct tag\", peek(p))\n"
    "    tag_tok : take(p)\n"
    "    tag : tag_tok[\"text\"]\n"
    "    if at(p, \"{\"):\n"
    "        fields : parse_struct_fields(p)\n"
    "        p[\"structs\"][tag] : fields\n"
    "        if at(p, \";\"):\n"
    "            take(p)\n"
    "            z : node(\"Seq\", x)\n"
    "            z[\"body\"] : []\n"
    "            return z\n"
    "        # struct S {..} name;\n"
    "        return finish_struct_var_decl(p, x, tag)\n"
    "    # struct S name; / struct S name = {...};\n"
    "    p[\"pos\"] : save\n"
    "    d : try_parse_decl(p)\n"
    "    if d != None:\n"
    "        return d\n"
    "    fail(p, \"invalid struct declaration\", x)\n"
    "\n"
    "def finish_struct_var_decl(p, x, tag):\n"
    "    if not kind(p, \"NAME\"):\n"
    "        fail(p, \"expected declarator\", peek(p))\n"
    "    return parse_decl_list_after_type(p, x, tag)\n"
    "\n"
    "def parse_enum(p):\n"
    "    x : take(p)\n"
    "    tag : None\n"
    "    if kind(p, \"NAME\"):\n"
    "        tag : take(p)[\"text\"]\n"
    "    need(p, \"{\")\n"
    "    seq : node(\"Seq\", x)\n"
    "    seq[\"body\"] : []\n"
    "    next_val : 0\n"
    "    while not at(p, \"}\") and not kind(p, \"END\"):\n"
    "        if not kind(p, \"NAME\"):\n"
    "            fail(p, \"expected enumerator\", peek(p))\n"
    "        et : take(p)\n"
    "        name : ident(p, et)\n"
    "        val : next_val\n"
    "        if at(p, \"=\"):\n"
    "            take(p)\n"
    "            if not kind(p, \"NUMBER\"):\n"
    "                fail(p, \"enum value must be a number literal\", peek(p))\n"
    "            vt : take(p)\n"
    "            val : int(vt[\"text\"])\n"
    "        c : node(\"Const\", et)\n"
    "        c[\"value\"] : str(val)\n"
    "        c[\"kind\"] : \"number\"\n"
    "        seq[\"body\"].append(assign_name(et, name, c))\n"
    "        next_val : val + 1\n"
    "        if at(p, \",\"):\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "            continue\n"
    "        break\n"
    "    need(p, \"}\")\n"
    "    if tag != None:\n"
    "        p[\"enums\"][tag] : True\n"
    "    need(p, \";\")\n"
    "    if len(seq[\"body\"]) = 0:\n"
    "        z : node(\"Seq\", x)\n"
    "        z[\"body\"] : []\n"
    "        return z\n"
    "    return seq\n"
    "\n"
    "def empty_stmt(x):\n"
    "    z : node(\"Seq\", x)\n"
    "    z[\"body\"] : []\n"
    "    return z\n"
    "\n"
    "def parse_typedef(p):\n"
    "    x : take(p)\n"
    "    if at(p, \"struct\"):\n"
    "        take(p)\n"
    "        tag : None\n"
    "        if kind(p, \"NAME\"):\n"
    "            tag : take(p)[\"text\"]\n"
    "        if at(p, \"{\"):\n"
    "            fields : parse_struct_fields(p)\n"
    "            if tag = None:\n"
    "                tag : \"__c_anon_\" + str(len(p[\"structs\"]))\n"
    "            p[\"structs\"][tag] : fields\n"
    "        elif tag = None:\n"
    "            fail(p, \"expected struct tag or body in typedef\", peek(p))\n"
    "        elif tag not in p[\"structs\"]:\n"
    "            p[\"structs\"][tag] : []\n"
    "        if not kind(p, \"NAME\"):\n"
    "            fail(p, \"expected typedef name\", peek(p))\n"
    "        alias : take(p)[\"text\"]\n"
    "        p[\"aliases\"][alias] : {\"struct\":tag}\n"
    "        need(p, \";\")\n"
    "        return empty_stmt(x)\n"
    "    if at(p, \"enum\"):\n"
    "        # typedef enum {..} Name; or typedef enum E Name;\n"
    "        take(p)\n"
    "        if kind(p, \"NAME\"):\n"
    "            take(p)\n"
    "        if at(p, \"{\"):\n"
    "            # parse enumerators as side effect via temporary\n"
    "            save_body : []\n"
    "            need(p, \"{\")\n"
    "            next_val : 0\n"
    "            seq : node(\"Seq\", x)\n"
    "            seq[\"body\"] : []\n"
    "            while not at(p, \"}\") and not kind(p, \"END\"):\n"
    "                if not kind(p, \"NAME\"):\n"
    "                    fail(p, \"expected enumerator\", peek(p))\n"
    "                et : take(p)\n"
    "                name : ident(p, et)\n"
    "                val : next_val\n"
    "                if at(p, \"=\"):\n"
    "                    take(p)\n"
    "                    if not kind(p, \"NUMBER\"):\n"
    "                        fail(p, \"enum value must be a number literal\", peek(p))\n"
    "                    vt : take(p)\n"
    "                    val : int(vt[\"text\"])\n"
    "                c : node(\"Const\", et)\n"
    "                c[\"value\"] : str(val)\n"
    "                c[\"kind\"] : \"number\"\n"
    "                seq[\"body\"].append(assign_name(et, name, c))\n"
    "                next_val : val + 1\n"
    "                if at(p, \",\"):\n"
    "                    take(p)\n"
    "                    if at(p, \"}\"):\n"
    "                        break\n"
    "                    continue\n"
    "                break\n"
    "            need(p, \"}\")\n"
    "            if not kind(p, \"NAME\"):\n"
    "                fail(p, \"expected typedef name\", peek(p))\n"
    "            alias : take(p)[\"text\"]\n"
    "            p[\"aliases\"][alias] : \"enum\"\n"
    "            need(p, \";\")\n"
    "            if len(seq[\"body\"]) = 0:\n"
    "                return empty_stmt(x)\n"
    "            return seq\n"
    "        if not kind(p, \"NAME\"):\n"
    "            fail(p, \"expected typedef name\", peek(p))\n"
    "        alias : take(p)[\"text\"]\n"
    "        p[\"aliases\"][alias] : \"enum\"\n"
    "        need(p, \";\")\n"
    "        return empty_stmt(x)\n"
    "    if not skip_type(p):\n"
    "        fail(p, \"expected type in typedef\", peek(p))\n"
    "    reject_pointer_type(p)\n"
    "    if not kind(p, \"NAME\"):\n"
    "        fail(p, \"expected typedef name\", peek(p))\n"
    "    alias : take(p)[\"text\"]\n"
    "    p[\"aliases\"][alias] : \"type\"\n"
    "    need(p, \";\")\n"
    "    return empty_stmt(x)\n"
    "\n"
    "def try_parse_func(p):\n"
    "    save : p[\"pos\"]\n"
    "    ok : skip_type(p)\n"
    "    if not ok:\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    reject_pointer_type(p)\n"
    "    if not kind(p, \"NAME\") or is_kw(peek(p)[\"text\"]):\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    name_tok : peek(p)\n"
    "    if peekn(p, 1)[\"text\"] != \"(\":\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    x : name_tok\n"
    "    take(p)\n"
    "    ident(p, name_tok)\n"
    "    z : node(\"FunctionDef\", x)\n"
    "    z[\"name\"] : name_tok[\"text\"]\n"
    "    z[\"decorators\"] : []\n"
    "    z[\"defaults\"] : []\n"
    "    if name_tok[\"text\"] = \"main\":\n"
    "        p[\"has_main\"] : True\n"
    "        args : parse_main_params(p)\n"
    "        z[\"args\"] : args\n"
    "        defaults : []\n"
    "        for a in args:\n"
    "            defaults.append(None)\n"
    "        z[\"defaults\"] : defaults\n"
    "        p[\"main_arity\"] : len(args)\n"
    "        z[\"body\"] : desugar_goto_body(p, parse_block(p), x)\n"
    "        return z\n"
    "    need(p, \"(\")\n"
    "    # Detect K&R: (a, b) vs (int a, int b) vs ()\n"
    "    knr : False\n"
    "    if not at(p, \")\"):\n"
    "        # Lookahead: if first token is NAME and not a type, K&R param names\n"
    "        if kind(p, \"NAME\") and not is_known_type_name(p, peek(p)[\"text\"]) and not is_type_mod(peek(p)[\"text\"]) and not is_storage(peek(p)[\"text\"]) and peek(p)[\"text\"] != \"struct\" and peek(p)[\"text\"] != \"enum\" and peek(p)[\"text\"] != \"void\":\n"
    "            knr : True\n"
    "    args : []\n"
    "    defaults : []\n"
    "    if knr:\n"
    "        while not at(p, \")\"):\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            ident(p, a)\n"
    "            args.append(a[\"text\"])\n"
    "            defaults.append(None)\n"
    "            if not at(p, \")\"):\n"
    "                need(p, \",\")\n"
    "        need(p, \")\")\n"
    "        # K&R declaration list\n"
    "        while not at(p, \"{\") and not kind(p, \"END\"):\n"
    "            if not skip_type(p):\n"
    "                fail(p, \"expected K&R parameter declaration\", peek(p))\n"
    "            reject_pointer_type(p)\n"
    "            while True:\n"
    "                if not kind(p, \"NAME\"):\n"
    "                    fail(p, \"expected parameter name\", peek(p))\n"
    "                take(p)\n"
    "                while at(p, \"[\"):\n"
    "                    take(p)\n"
    "                    if not at(p, \"]\"):\n"
    "                        fail(p, \"sized array parameters are unsupported\", peek(p))\n"
    "                    take(p)\n"
    "                if at(p, \",\"):\n"
    "                    take(p)\n"
    "                    reject_pointer_type(p)\n"
    "                    continue\n"
    "                break\n"
    "            need(p, \";\")\n"
    "        z[\"args\"] : args\n"
    "        z[\"defaults\"] : defaults\n"
    "        z[\"body\"] : desugar_goto_body(p, parse_block(p), x)\n"
    "        return z\n"
    "    if not at(p, \")\"):\n"
    "        while True:\n"
    "            if at(p, \"void\") and peekn(p, 1)[\"text\"] = \")\":\n"
    "                take(p)\n"
    "                break\n"
    "            if not skip_type(p):\n"
    "                fail(p, \"expected parameter type\", peek(p))\n"
    "            reject_pointer_type(p)\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            while at(p, \"[\"):\n"
    "                take(p)\n"
    "                if not at(p, \"]\"):\n"
    "                    fail(p, \"sized array parameters are unsupported\", peek(p))\n"
    "                take(p)\n"
    "            ident(p, a)\n"
    "            args.append(a[\"text\"])\n"
    "            defaults.append(None)\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "    need(p, \")\")\n"
    "    z[\"args\"] : args\n"
    "    z[\"defaults\"] : defaults\n"
    "    z[\"body\"] : desugar_goto_body(p, parse_block(p), x)\n"
    "    return z\n"
    "\n"
    "def parse_init_value(p, struct_tag):\n"
    "    x : peek(p)\n"
    "    if at(p, \"{\"):\n"
    "        if struct_tag != None and struct_tag in p[\"structs\"]:\n"
    "            take(p)\n"
    "            elts : []\n"
    "            if not at(p, \"}\"):\n"
    "                while True:\n"
    "                    elts.append(parse_expr(p))\n"
    "                    if not at(p, \",\"):\n"
    "                        break\n"
    "                    take(p)\n"
    "                    if at(p, \"}\"):\n"
    "                        break\n"
    "            need(p, \"}\")\n"
    "            return make_struct_dict(p, x, struct_tag, elts)\n"
    "        return parse_array_init(p, x)\n"
    "    return parse_expr(p)\n"
    "\n"
    "def parse_decl_list_after_type(p, x, struct_tag):\n"
    "    seq : node(\"Seq\", x)\n"
    "    seq[\"body\"] : []\n"
    "    while True:\n"
    "        reject_pointer_type(p)\n"
    "        if not kind(p, \"NAME\") or is_kw(peek(p)[\"text\"]):\n"
    "            fail(p, \"expected declarator name\", peek(p))\n"
    "        name_tok : take(p)\n"
    "        is_array : False\n"
    "        while at(p, \"[\"):\n"
    "            is_array : True\n"
    "            take(p)\n"
    "            if not at(p, \"]\"):\n"
    "                if kind(p, \"NUMBER\"):\n"
    "                    take(p)\n"
    "                else:\n"
    "                    fail(p, \"sized array declarations require a numeric bound or []\", peek(p))\n"
    "            need(p, \"]\")\n"
    "        ident(p, name_tok)\n"
    "        value : None\n"
    "        if at(p, \"=\"):\n"
    "            take(p)\n"
    "            if is_array:\n"
    "                value : parse_init_value(p, None)\n"
    "            else:\n"
    "                value : parse_init_value(p, struct_tag)\n"
    "        else:\n"
    "            if is_array:\n"
    "                fail(p, \"array declarations require an initializer\", peek(p))\n"
    "            elif struct_tag != None and struct_tag in p[\"structs\"]:\n"
    "                value : make_struct_dict(p, name_tok, struct_tag, None)\n"
    "            else:\n"
    "                value : const_zero(name_tok)\n"
    "        z : node(\"Assign\", name_tok)\n"
    "        tgt : node(\"Name\", name_tok)\n"
    "        tgt[\"value\"] : name_tok[\"text\"]\n"
    "        z[\"target\"] : tgt\n"
    "        z[\"value\"] : value\n"
    "        seq[\"body\"].append(z)\n"
    "        if at(p, \",\"):\n"
    "            take(p)\n"
    "            continue\n"
    "        break\n"
    "    need(p, \";\")\n"
    "    if len(seq[\"body\"]) = 1:\n"
    "        return seq[\"body\"][0]\n"
    "    return seq\n"
    "\n"
    "def try_parse_decl(p):\n"
    "    save : p[\"pos\"]\n"
    "    ok : skip_type(p)\n"
    "    if not ok:\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    struct_tag : peek_struct_tag_after_type(p, save)\n"
    "    reject_pointer_type(p)\n"
    "    if not kind(p, \"NAME\") or is_kw(peek(p)[\"text\"]):\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    # Must look like a declarator: name then = , ; or [\n"
    "    j : 0\n"
    "    if peekn(p, j)[\"kind\"] != \"NAME\":\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    j += 1\n"
    "    while peekn(p, j)[\"text\"] = \"[\":\n"
    "        if peekn(p, j + 1)[\"text\"] = \"]\":\n"
    "            j += 2\n"
    "        elif peekn(p, j + 1)[\"kind\"] = \"NUMBER\" and peekn(p, j + 2)[\"text\"] = \"]\":\n"
    "            j += 3\n"
    "        else:\n"
    "            p[\"pos\"] : save\n"
    "            return None\n"
    "    nxt : peekn(p, j)[\"text\"]\n"
    "    if nxt != \"=\" and nxt != \",\" and nxt != \";\":\n"
    "        p[\"pos\"] : save\n"
    "        return None\n"
    "    x : peek(p)\n"
    "    return parse_decl_list_after_type(p, x, struct_tag)\n"
    "\n"
    "def parse_block(p):\n"
    "    lb : need(p, \"{\")\n"
    "    xs : []\n"
    "    while not at(p, \"}\") and not kind(p, \"END\"):\n"
    "        xs.append(parse_stmt(p))\n"
    "    need(p, \"}\")\n"
    "    if len(xs) = 0:\n"
    "        px : node(\"pass\", lb)\n"
    "        return [px]\n"
    "    return xs\n"
    "\n"
    "def parse_block_or_stmt(p):\n"
    "    if at(p, \"{\"):\n"
    "        return parse_block(p)\n"
    "    return [parse_stmt(p)]\n"
    "\n"
    "def parse_return(p):\n"
    "    x : take(p)\n"
    "    z : node(\"Return\", x)\n"
    "    z[\"value\"] : None\n"
    "    if not at(p, \";\"):\n"
    "        z[\"value\"] : parse_expr(p)\n"
    "    need(p, \";\")\n"
    "    return z\n"
    "\n"
    "def parse_if(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    test : parse_expr(p)\n"
    "    need(p, \")\")\n"
    "    z : node(\"If\", x)\n"
    "    z[\"test\"] : test\n"
    "    z[\"body\"] : parse_block_or_stmt(p)\n"
    "    z[\"elifs\"] : []\n"
    "    z[\"orelse\"] : []\n"
    "    while at(p, \"else\") and peekn(p, 1)[\"text\"] = \"if\":\n"
    "        e : take(p)\n"
    "        take(p)\n"
    "        need(p, \"(\")\n"
    "        et : parse_expr(p)\n"
    "        need(p, \")\")\n"
    "        eb : parse_block_or_stmt(p)\n"
    "        z[\"elifs\"].append({\"test\":et, \"body\":eb, \"line\":e[\"line\"], \"col\":e[\"col\"]})\n"
    "    if at(p, \"else\"):\n"
    "        take(p)\n"
    "        z[\"orelse\"] : parse_block_or_stmt(p)\n"
    "    return z\n"
    "\n"
    "def parse_while(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    t : parse_expr(p)\n"
    "    need(p, \")\")\n"
    "    z : node(\"While\", x)\n"
    "    z[\"test\"] : t\n"
    "    z[\"body\"] : parse_block_or_stmt(p)\n"
    "    return z\n"
    "\n"
    "def parse_do_while(p):\n"
    "    x : take(p)\n"
    "    body : parse_block_or_stmt(p)\n"
    "    need(p, \"while\")\n"
    "    need(p, \"(\")\n"
    "    cond : parse_expr(p)\n"
    "    need(p, \")\")\n"
    "    need(p, \";\")\n"
    "    w : node(\"While\", x)\n"
    "    w[\"test\"] : const_true(x)\n"
    "    b2 : []\n"
    "    for s in body:\n"
    "        b2.append(s)\n"
    "    # if not cond: break\n"
    "    iff : node(\"If\", x)\n"
    "    un : node(\"Unary\", x)\n"
    "    un[\"op\"] : \"not\"\n"
    "    un[\"value\"] : cond\n"
    "    iff[\"test\"] : un\n"
    "    iff[\"body\"] : [node(\"break\", x)]\n"
    "    iff[\"elifs\"] : []\n"
    "    iff[\"orelse\"] : []\n"
    "    b2.append(iff)\n"
    "    w[\"body\"] : b2\n"
    "    return w\n"
    "\n"
    "def parse_switch(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    expr : parse_expr(p)\n"
    "    need(p, \")\")\n"
    "    need(p, \"{\")\n"
    "    p[\"goto_tmp\"] += 1\n"
    "    tmp : \"__c_sw\" + str(p[\"goto_tmp\"])\n"
    "    seq : node(\"Seq\", x)\n"
    "    seq[\"body\"] : [assign_name(x, tmp, expr)]\n"
    "    cases : []\n"
    "    default_body : None\n"
    "    while not at(p, \"}\") and not kind(p, \"END\"):\n"
    "        if at(p, \"case\"):\n"
    "            cx : take(p)\n"
    "            val : parse_expr(p)\n"
    "            need(p, \":\")\n"
    "            cb : []\n"
    "            while not at(p, \"case\") and not at(p, \"default\") and not at(p, \"}\") and not kind(p, \"END\"):\n"
    "                cb.append(parse_stmt(p))\n"
    "            # Reject fall-through: body must end with break (or be empty only if... no, empty is fall-through)\n"
    "            if len(cb) = 0:\n"
    "                fail(p, \"switch fall-through is unsupported\", cx)\n"
    "            last : cb[len(cb) - 1]\n"
    "            if last[\"t\"] != \"break\":\n"
    "                # allow return as terminator too\n"
    "                if last[\"t\"] != \"Return\":\n"
    "                    fail(p, \"switch fall-through is unsupported (missing break)\", last)\n"
    "            # strip trailing break for if-body\n"
    "            body_out : []\n"
    "            i : 0\n"
    "            while i < len(cb):\n"
    "                if i = len(cb) - 1 and cb[i][\"t\"] = \"break\":\n"
    "                    break\n"
    "                body_out.append(cb[i])\n"
    "                i += 1\n"
    "            if len(body_out) = 0:\n"
    "                body_out.append(node(\"pass\", cx))\n"
    "            cases.append({\"test\":val, \"body\":body_out, \"line\":cx[\"line\"], \"col\":cx[\"col\"]})\n"
    "        elif at(p, \"default\"):\n"
    "            dx : take(p)\n"
    "            need(p, \":\")\n"
    "            db : []\n"
    "            while not at(p, \"case\") and not at(p, \"default\") and not at(p, \"}\") and not kind(p, \"END\"):\n"
    "                db.append(parse_stmt(p))\n"
    "            if len(db) > 0:\n"
    "                last : db[len(db) - 1]\n"
    "                if last[\"t\"] = \"break\":\n"
    "                    db : db[:len(db) - 1]\n"
    "            if len(db) = 0:\n"
    "                db : [node(\"pass\", dx)]\n"
    "            default_body : db\n"
    "        else:\n"
    "            fail(p, \"expected case or default in switch\", peek(p))\n"
    "    need(p, \"}\")\n"
    "    if len(cases) = 0 and default_body = None:\n"
    "        return seq\n"
    "    # Build if/elif chain\n"
    "    first : cases[0] if len(cases) > 0 else None\n"
    "    if first != None:\n"
    "        iff : node(\"If\", x)\n"
    "        cmp : node(\"Compare\", x)\n"
    "        cmp[\"left\"] : name_node(x, tmp)\n"
    "        cmp[\"op\"] : \"==\"\n"
    "        cmp[\"right\"] : first[\"test\"]\n"
    "        iff[\"test\"] : cmp\n"
    "        iff[\"body\"] : first[\"body\"]\n"
    "        iff[\"elifs\"] : []\n"
    "        i : 1\n"
    "        while i < len(cases):\n"
    "            c : cases[i]\n"
    "            cmpi : node(\"Compare\", x)\n"
    "            cmpi[\"left\"] : name_node(x, tmp)\n"
    "            cmpi[\"op\"] : \"==\"\n"
    "            cmpi[\"right\"] : c[\"test\"]\n"
    "            iff[\"elifs\"].append({\"test\":cmpi, \"body\":c[\"body\"], \"line\":c[\"line\"], \"col\":c[\"col\"]})\n"
    "            i += 1\n"
    "        iff[\"orelse\"] : default_body if default_body != None else []\n"
    "        seq[\"body\"].append(iff)\n"
    "    elif default_body != None:\n"
    "        for s in default_body:\n"
    "            seq[\"body\"].append(s)\n"
    "    return seq\n"
    "\n"
    "def parse_for(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    init : None\n"
    "    if not at(p, \";\"):\n"
    "        init : parse_for_clause(p)\n"
    "    need(p, \";\")\n"
    "    cond : None\n"
    "    if not at(p, \";\"):\n"
    "        cond : parse_expr(p)\n"
    "    need(p, \";\")\n"
    "    upd : None\n"
    "    if not at(p, \")\"):\n"
    "        upd : parse_assign_no_semi(p)\n"
    "    need(p, \")\")\n"
    "    body : parse_block_or_stmt(p)\n"
    "    w : node(\"While\", x)\n"
    "    if cond = None:\n"
    "        w[\"test\"] : const_true(x)\n"
    "    else:\n"
    "        w[\"test\"] : cond\n"
    "    b2 : []\n"
    "    for s in body:\n"
    "        b2.append(s)\n"
    "    if upd != None:\n"
    "        b2.append(upd)\n"
    "    w[\"body\"] : b2\n"
    "    seq : node(\"Seq\", x)\n"
    "    stmts : []\n"
    "    if init != None:\n"
    "        stmts.append(init)\n"
    "    stmts.append(w)\n"
    "    seq[\"body\"] : stmts\n"
    "    return seq\n"
    "\n"
    "def parse_for_clause(p):\n"
    "    x : peek(p)\n"
    "    save : p[\"pos\"]\n"
    "    if skip_type(p):\n"
    "        reject_pointer_type(p)\n"
    "        if kind(p, \"NAME\") and not is_kw(peek(p)[\"text\"]) and peekn(p, 1)[\"text\"] = \"=\":\n"
    "            nt : take(p)\n"
    "            ident(p, nt)\n"
    "            need(p, \"=\")\n"
    "            v : parse_expr(p)\n"
    "            z : node(\"Assign\", x)\n"
    "            tg : node(\"Name\", x)\n"
    "            tg[\"value\"] : nt[\"text\"]\n"
    "            z[\"target\"] : tg\n"
    "            z[\"value\"] : v\n"
    "            return z\n"
    "    p[\"pos\"] : save\n"
    "    return parse_assign_no_semi(p)\n"
    "\n"
    "def make_bit_call(x, fname, args):\n"
    "    z : node(\"Call\", x)\n"
    "    fn : node(\"Name\", x)\n"
    "    fn[\"value\"] : fname\n"
    "    z[\"func\"] : fn\n"
    "    z[\"args\"] : args\n"
    "    z[\"kwargs\"] : []\n"
    "    return z\n"
    "\n"
    "def lower_bit_binop(left, op, right):\n"
    "    if op in bit_binop_names:\n"
    "        return make_bit_call(left, bit_binop_names[op], [left, right])\n"
    "    q : node(\"BinOp\", left)\n"
    "    q[\"left\"] : left\n"
    "    q[\"op\"] : op\n"
    "    q[\"right\"] : right\n"
    "    return q\n"
    "\n"
    "def parse_assign_no_semi(p):\n"
    "    x : peek(p)\n"
    "    # Prefix ++/-- as statement\n"
    "    if at(p, \"++\") or at(p, \"--\"):\n"
    "        tt : take(p)[\"text\"]\n"
    "        left : parse_postfix(p)\n"
    "        validate_target(p, left)\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        z[\"op\"] : \"+=\" if tt = \"++\" else \"-=\"\n"
    "        z[\"value\"] : const_zero(x)\n"
    "        z[\"value\"][\"value\"] : \"1\"\n"
    "        return z\n"
    "    left : parse_expr(p)\n"
    "    tt : peek(p)[\"text\"]\n"
    "    if tt = \"=\":\n"
    "        take(p)\n"
    "        val : parse_expr(p)\n"
    "        z : node(\"Assign\", x)\n"
    "        z[\"target\"] : left\n"
    "        z[\"value\"] : val\n"
    "        validate_target(p, left)\n"
    "        return z\n"
    "    if tt in [\"+=\", \"-=\", \"*=\", \"/=\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        validate_target(p, left)\n"
    "        z[\"op\"] : op\n"
    "        z[\"value\"] : parse_expr(p)\n"
    "        return z\n"
    "    if tt = \"%=\":\n"
    "        take(p)\n"
    "        val : parse_expr(p)\n"
    "        validate_target(p, left)\n"
    "        # x : (x % y)\n"
    "        z : node(\"Assign\", x)\n"
    "        z[\"target\"] : left\n"
    "        bo : node(\"BinOp\", x)\n"
    "        bo[\"left\"] : left\n"
    "        bo[\"op\"] : \"%\"\n"
    "        bo[\"right\"] : val\n"
    "        z[\"value\"] : bo\n"
    "        return z\n"
    "    if tt in bit_aug_ops:\n"
    "        op : take(p)[\"text\"]\n"
    "        val : parse_expr(p)\n"
    "        validate_target(p, left)\n"
    "        z : node(\"Assign\", x)\n"
    "        z[\"target\"] : left\n"
    "        z[\"value\"] : make_bit_call(x, bit_aug_ops[op], [left, val])\n"
    "        return z\n"
    "    if tt = \"++\" or tt = \"--\":\n"
    "        take(p)\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        validate_target(p, left)\n"
    "        z[\"op\"] : \"+=\" if tt = \"++\" else \"-=\"\n"
    "        one : node(\"Const\", x)\n"
    "        one[\"value\"] : \"1\"\n"
    "        one[\"kind\"] : \"number\"\n"
    "        z[\"value\"] : one\n"
    "        return z\n"
    "    z : node(\"Expr\", x)\n"
    "    z[\"value\"] : left\n"
    "    return z\n"
    "\n"
    "def parse_expr_stmt(p):\n"
    "    z : parse_assign_no_semi(p)\n"
    "    need(p, \";\")\n"
    "    return z\n"
    "\n"
    "def validate_target(p, x):\n"
    "    if x[\"t\"] = \"Name\" or x[\"t\"] = \"Attr\" or x[\"t\"] = \"Subscript\":\n"
    "        return\n"
    "    fail(p, \"unsupported assignment target\", x)\n"
    "\n"
    "def parse_expr(p):\n"
    "    return parse_ternary(p)\n"
    "\n"
    "def parse_ternary(p):\n"
    "    c : parse_or(p)\n"
    "    if at(p, \"?\"):\n"
    "        take(p)\n"
    "        a : parse_expr(p)\n"
    "        need(p, \":\")\n"
    "        b : parse_expr(p)\n"
    "        z : node(\"IfExp\", c)\n"
    "        z[\"body\"] : a\n"
    "        z[\"test\"] : c\n"
    "        z[\"orelse\"] : b\n"
    "        return z\n"
    "    return c\n"
    "\n"
    "def parse_or(p):\n"
    "    xs : [parse_and(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"||\"):\n"
    "        take(p)\n"
    "        xs.append(parse_and(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"or\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_and(p):\n"
    "    xs : [parse_bitor(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"&&\"):\n"
    "        take(p)\n"
    "        xs.append(parse_bitor(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"and\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_bitor(p):\n"
    "    z : parse_bitxor(p)\n"
    "    while at(p, \"|\"):\n"
    "        take(p)\n"
    "        z : lower_bit_binop(z, \"|\", parse_bitxor(p))\n"
    "    return z\n"
    "\n"
    "def parse_bitxor(p):\n"
    "    z : parse_bitand(p)\n"
    "    while at(p, \"^\"):\n"
    "        take(p)\n"
    "        z : lower_bit_binop(z, \"^\", parse_bitand(p))\n"
    "    return z\n"
    "\n"
    "def parse_bitand(p):\n"
    "    z : parse_compare(p)\n"
    "    while at(p, \"&\"):\n"
    "        take(p)\n"
    "        z : lower_bit_binop(z, \"&\", parse_compare(p))\n"
    "    return z\n"
    "\n"
    "def parse_compare(p):\n"
    "    left : parse_shift(p)\n"
    "    if peek(p)[\"text\"] in [\"==\", \"!=\", \"<\", \"<=\", \">\", \">=\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        right : parse_shift(p)\n"
    "        z : node(\"Compare\", left)\n"
    "        z[\"left\"] : left\n"
    "        z[\"op\"] : op\n"
    "        z[\"right\"] : right\n"
    "        return z\n"
    "    return left\n"
    "\n"
    "def parse_shift(p):\n"
    "    z : parse_add(p)\n"
    "    while at(p, \"<<\") or at(p, \">>\"):\n"
    "        op : take(p)[\"text\"]\n"
    "        z : lower_bit_binop(z, op, parse_add(p))\n"
    "    return z\n"
    "\n"
    "def parse_add(p):\n"
    "    z : parse_mul(p)\n"
    "    while peek(p)[\"text\"] = \"+\" or peek(p)[\"text\"] = \"-\":\n"
    "        op : take(p)[\"text\"]\n"
    "        q : node(\"BinOp\", z)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : op\n"
    "        q[\"right\"] : parse_mul(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_mul(p):\n"
    "    z : parse_unary(p)\n"
    "    while peek(p)[\"text\"] in [\"*\", \"/\", \"%\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        q : node(\"BinOp\", z)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : op\n"
    "        q[\"right\"] : parse_unary(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_unary(p):\n"
    "    tt : peek(p)[\"text\"]\n"
    "    if tt = \"!\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"not\"\n"
    "        z[\"value\"] : parse_unary(p)\n"
    "        return z\n"
    "    if tt = \"-\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"-\"\n"
    "        z[\"value\"] : parse_unary(p)\n"
    "        return z\n"
    "    if tt = \"+\":\n"
    "        take(p)\n"
    "        return parse_unary(p)\n"
    "    if tt = \"~\":\n"
    "        x : take(p)\n"
    "        return make_bit_call(x, \"bnot\", [parse_unary(p)])\n"
    "    if tt = \"++\" or tt = \"--\":\n"
    "        fail(p, \"prefix increment/decrement only supported as a statement\", peek(p))\n"
    "    if tt = \"&\":\n"
    "        fail(p, \"address-of is unsupported\", peek(p))\n"
    "    if tt = \"*\":\n"
    "        fail(p, \"pointer dereference is unsupported\", peek(p))\n"
    "    return parse_postfix(p)\n"
    "\n"
    "def parse_postfix(p):\n"
    "    z : parse_atom(p)\n"
    "    while True:\n"
    "        if at(p, \".\"):\n"
    "            x : take(p)\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            # Struct field \20622 subscript with string key\n"
    "            q : node(\"Subscript\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"slice\"] : const_str(x, a[\"text\"])\n"
    "            z : q\n"
    "        elif at(p, \"->\"):\n"
    "            fail(p, \"pointer member access is unsupported\", peek(p))\n"
    "        elif at(p, \"(\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Call\", x)\n"
    "            q[\"func\"] : z\n"
    "            q[\"args\"] : []\n"
    "            q[\"kwargs\"] : []\n"
    "            if not at(p, \")\"):\n"
    "                while True:\n"
    "                    q[\"args\"].append(parse_expr(p))\n"
    "                    if not at(p, \",\"):\n"
    "                        break\n"
    "                    take(p)\n"
    "            need(p, \")\")\n"
    "            z : q\n"
    "        elif at(p, \"[\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Subscript\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"slice\"] : parse_index(p)\n"
    "            need(p, \"]\")\n"
    "            z : q\n"
    "        else:\n"
    "            break\n"
    "    return z\n"
    "\n"
    "def parse_index(p):\n"
    "    x : peek(p)\n"
    "    lower : None\n"
    "    if not at(p, \"]\"):\n"
    "        lower : parse_expr(p)\n"
    "    return lower\n"
    "\n"
    "def parse_array_init(p, x):\n"
    "    need(p, \"{\")\n"
    "    z : node(\"List\", x)\n"
    "    z[\"elts\"] : []\n"
    "    if not at(p, \"}\"):\n"
    "        while True:\n"
    "            z[\"elts\"].append(parse_expr(p))\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "    need(p, \"}\")\n"
    "    return z\n"
    "\n"
    "def looking_at_cast(p):\n"
    "    # After '(', is this a type then ')'?\n"
    "    save : p[\"pos\"]\n"
    "    if not skip_type(p):\n"
    "        p[\"pos\"] : save\n"
    "        return False\n"
    "    reject_pointer_type(p)\n"
    "    ok : at(p, \")\")\n"
    "    p[\"pos\"] : save\n"
    "    return ok\n"
    "\n"
    "def parse_atom(p):\n"
    "    x : peek(p)\n"
    "    if kind(p, \"NUMBER\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"text\"]\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if kind(p, \"STRING\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"val\"][\"s\"]\n"
    "        z[\"kind\"] : \"string\"\n"
    "        return z\n"
    "    if at(p, \"true\") or at(p, \"false\") or at(p, \"NULL\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : \"True\" if x[\"text\"] = \"true\" else (\"False\" if x[\"text\"] = \"false\" else \"None\")\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if kind(p, \"NAME\"):\n"
    "        take(p)\n"
    "        if is_kw(x[\"text\"]):\n"
    "            fail(p, \"unexpected keyword '\" + x[\"text\"] + \"'\", x)\n"
    "        if x[\"text\"] in c_forbidden_names:\n"
    "            fail(p, x[\"text\"] + \" is unsupported\", x)\n"
    "        z : node(\"Name\", x)\n"
    "        z[\"value\"] : ident(p, x)\n"
    "        x[\"text\"] : z[\"value\"]\n"
    "        return z\n"
    "    if at(p, \"(\"):\n"
    "        take(p)\n"
    "        if looking_at_cast(p):\n"
    "            skip_type(p)\n"
    "            reject_pointer_type(p)\n"
    "            need(p, \")\")\n"
    "            return parse_unary(p)\n"
    "        z : parse_expr(p)\n"
    "        need(p, \")\")\n"
    "        return z\n"
    "    if at(p, \"{\"):\n"
    "        return parse_array_init(p, x)\n"
    "    fail(p, \"unsupported expression\", x)\n"
    "\n"
    "def pad(n):\n"
    "    return \"    \" * n\n"
    "\n"
    "def render(ast, state):\n"
    "    state[\"comments\"] : ast[\"comments\"]\n"
    "    state[\"inline\"] : ast[\"inline\"]\n"
    "    state[\"last_comment\"] : 0\n"
    "    state[\"filename\"] : ast[\"filename\"]\n"
    "    state[\"structs\"] : ast[\"structs\"] if \"structs\" in ast else {}\n"
    "    lines : render_body(ast[\"body\"], state, 0, True)\n"
    "    for k in state[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > state[\"last_comment\"]:\n"
    "            lines.append(state[\"comments\"][k])\n"
    "    text : \"\"\n"
    "    for line in lines:\n"
    "        if line != \"\":\n"
    "            text += line + \"\\n\"\n"
    "    return text\n"
    "\n"
    "def before_comments(st, line, indent):\n"
    "    out : []\n"
    "    for k in st[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > st[\"last_comment\"] and kn < line:\n"
    "            out.append(pad(indent) + st[\"comments\"][k])\n"
    "            st[\"last_comment\"] : kn\n"
    "    return out\n"
    "\n"
    "def render_body(body, st, indent, doc_ok):\n"
    "    out : []\n"
    "    i : 0\n"
    "    while i < len(body):\n"
    "        s : body[i]\n"
    "        cs : before_comments(st, s[\"line\"], indent)\n"
    "        for c in cs:\n"
    "            out.append(c)\n"
    "        rs : render_stmt(s, st, indent)\n"
    "        key : str(s[\"line\"])\n"
    "        if key in st[\"inline\"] and len(rs) > 0:\n"
    "            rs[0] : rs[0] + \"  \" + st[\"inline\"][key]\n"
    "        for q in rs:\n"
    "            if q != \"\":\n"
    "                out.append(q)\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def render_stmt(s, st, ind):\n"
    "    p : pad(ind)\n"
    "    t : s[\"t\"]\n"
    "    if t = \"Seq\":\n"
    "        out : []\n"
    "        for c in s[\"body\"]:\n"
    "            for q in render_stmt(c, st, ind):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"Assign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" : \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"AugAssign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" \" + s[\"op\"] + \" \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"Return\":\n"
    "        return [p + (\"return\" if s[\"value\"] = None else \"return \" + expr_text(s[\"value\"], st))]\n"
    "    if t = \"break\" or t = \"continue\" or t = \"pass\":\n"
    "        return [p + t]\n"
    "    if t = \"Label\":\n"
    "        return [p + \"pass\"]\n"
    "    if t = \"Goto\":\n"
    "        return [p + \"__c_goto : \" + quote_string(s[\"name\"]), p + \"continue\"]\n"
    "    if t = \"Expr\":\n"
    "        return [p + expr_text(s[\"value\"], st)]\n"
    "    if t = \"FunctionDef\":\n"
    "        out : []\n"
    "        for d in s[\"decorators\"]:\n"
    "            out.append(p + \"@\" + expr_text(d, st))\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(s[\"args\"]):\n"
    "            q : s[\"args\"][i]\n"
    "            if s[\"defaults\"][i] != None:\n"
    "                q += \":\" + expr_text(s[\"defaults\"][i], st)\n"
    "            parts.append(q)\n"
    "            i += 1\n"
    "        out.append(p + \"def \" + s[\"name\"] + \"(\" + join_text(parts, \", \") + \"):\")\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, True):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"If\":\n"
    "        out : [p + \"if \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        for e in s[\"elifs\"]:\n"
    "            out.append(p + \"elif \" + expr_text(e[\"test\"], st) + \":\")\n"
    "            for q in render_body(e[\"body\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        if len(s[\"orelse\"]) > 0:\n"
    "            out.append(p + \"else:\")\n"
    "            for q in render_body(s[\"orelse\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"While\":\n"
    "        out : [p + \"while \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    return []\n"
    "\n"
    "def join_text(xs, sep):\n"
    "    out : \"\"\n"
    "    i : 0\n"
    "    while i < len(xs):\n"
    "        if i > 0:\n"
    "            out += sep\n"
    "        out += xs[i]\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def target_text(x, st):\n"
    "    if x[\"t\"] = \"Tuple\" or x[\"t\"] = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(target_text(e, st))\n"
    "        return join_text(parts, \", \")\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def slice_text(x, st):\n"
    "    if x[\"t\"] = \"Slice\":\n"
    "        a : \"\" if x[\"lower\"] = None else expr_text(x[\"lower\"], st)\n"
    "        b : \"\" if x[\"upper\"] = None else expr_text(x[\"upper\"], st)\n"
    "        q : a + \":\" + b\n"
    "        if x[\"step\"] != None:\n"
    "            q += \":\" + expr_text(x[\"step\"], st)\n"
    "        return q\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def expr_text(x, st):\n"
    "    t : x[\"t\"]\n"
    "    if t = \"Name\":\n"
    "        return x[\"value\"]\n"
    "    if t = \"Const\":\n"
    "        if x[\"kind\"] = \"string\":\n"
    "            return quote_string(x[\"value\"])\n"
    "        return x[\"value\"]\n"
    "    if t = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"[\" + join_text(parts, \", \") + \"]\"\n"
    "    if t = \"Dict\":\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(x[\"keys\"]):\n"
    "            parts.append(expr_text(x[\"keys\"][i], st) + \": \" + expr_text(x[\"values\"][i], st))\n"
    "            i += 1\n"
    "        return \"{\" + join_text(parts, \", \") + \"}\"\n"
    "    if t = \"Attr\":\n"
    "        return expr_text(x[\"value\"], st) + \"[\" + quote_string(x[\"attr\"]) + \"]\"\n"
    "    if t = \"Subscript\":\n"
    "        return expr_text(x[\"value\"], st) + \"[\" + slice_text(x[\"slice\"], st) + \"]\"\n"
    "    if t = \"Unary\":\n"
    "        return \"(\" + (\"not \" if x[\"op\"] = \"not\" else \"-\") + expr_text(x[\"value\"], st) + \")\"\n"
    "    if t = \"BinOp\":\n"
    "        if x[\"op\"] = \"+\" and (is_stringy(x[\"left\"]) or is_stringy(x[\"right\"])):\n"
    "            return \"(\" + string_operand(x[\"left\"], st) + \" + \" + string_operand(x[\"right\"], st) + \")\"\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + x[\"op\"] + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"BoolOp\":\n"
    "        parts : []\n"
    "        for e in x[\"values\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"(\" + join_text(parts, \" \" + x[\"op\"] + \" \") + \")\"\n"
    "    if t = \"Compare\":\n"
    "        op : \"=\" if x[\"op\"] = \"==\" else x[\"op\"]\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + op + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"IfExp\":\n"
    "        return expr_text(x[\"body\"], st) + \" if \" + expr_text(x[\"test\"], st) + \" else \" + expr_text(x[\"orelse\"], st)\n"
    "    if t = \"Call\":\n"
    "        lowered : lower_call(x, st)\n"
    "        if lowered != None:\n"
    "            return lowered\n"
    "        parts : []\n"
    "        for e in x[\"args\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return expr_text(x[\"func\"], st) + \"(\" + join_text(parts, \", \") + \")\"\n"
    "    return \"\"\n"
    "\n"
    "def is_stringy(x):\n"
    "    if x[\"t\"] = \"Const\" and x[\"kind\"] = \"string\":\n"
    "        return True\n"
    "    if x[\"t\"] = \"BinOp\" and x[\"op\"] = \"+\" and (is_stringy(x[\"left\"]) or is_stringy(x[\"right\"])):\n"
    "        return True\n"
    "    return False\n"
    "\n"
    "def string_operand(x, st):\n"
    "    if is_stringy(x) and not (x[\"t\"] = \"BinOp\" and x[\"op\"] = \"+\"):\n"
    "        return expr_text(x, st)\n"
    "    if x[\"t\"] = \"BinOp\" and x[\"op\"] = \"+\" and (is_stringy(x[\"left\"]) or is_stringy(x[\"right\"])):\n"
    "        return expr_text(x, st)\n"
    "    return \"str(\" + expr_text(x, st) + \")\"\n"
    "\n"
    "def lower_call(x, st):\n"
    "    f : x[\"func\"]\n"
    "    if f[\"t\"] = \"Name\":\n"
    "        name : f[\"value\"]\n"
    "        if name = \"printf\" or name = \"puts\":\n"
    "            parts : []\n"
    "            for e in x[\"args\"]:\n"
    "                parts.append(expr_text(e, st))\n"
    "            return \"print(\" + join_text(parts, \", \") + \")\"\n"
    "    return None\n"
    "\n"
    "def transpile(source, filename):\n"
    "    ast : parse(source, filename)\n"
    "    return render(ast, {\"aliases\":ast[\"aliases\"]})\n"
    "\n"
    "def main():\n"
    "    return transpile_cli.run(argv, \"c2s.ie\", \"c\", transpile)\n"
    "\n"
    "# Run CLI only when this file is the entry script.\n"
    "if re_match(\"c2s\\\\.ie$\", argv[0]):\n"
    "    main()\n"
;
#endif /* SHAKTI_SHAKTI_C2S_SOURCE_H */
